SELECT '==A. TODOS LOS ARCHIVOS DE USUARIOS DEL GRUPO 660 (cualquier actividad) ==' as '';
SELECT 'Archivos de submit subidos por usuarios del grupo 660 (ordenados por fecha):' AS info_;
SELECT f.id, f.component, f.filearea, f.itemid AS assign_id_or_subid, u.firstname, u.lastname, f.filename, f.filesize, from_unixtime(f.timecreated) tc FROM isi_files f JOIN isi_user u ON u.id = f.userid JOIN isi_groups_members gm ON gm.userid = u.id AND gm.groupid = 660 WHERE f.component = 'assignsubmission_file' AND f.filename <> '.' ORDER BY f.timecreated;
SELECT '==B. ASIGN_ID DE ESOS ARCHIVOS (cuales son deleted vs activos) ==' as '';
SELECT 'itemid (assign_id), COUNT(*) AS num_files, MIN(CASE WHEN a.id IS NULL THEN 1 ELSE 0 END) AS all_deleted FROM isi_files f LEFT JOIN isi_assign a ON a.id = f.itemid WHERE f.component = 'assignsubmission_file' AND f.filename <> '.' AND f.contextid IN (SELECT id FROM isi_context WHERE contextlevel = 70 AND instanceid = 74) AND f.userid IN (SELECT userid FROM isi_groups_members WHERE groupid = 660) GROUP BY f.itemid ORDER BY all_deleted DESC, f.itemid;
SELECT '==C. ACTIVIDADES DELETED DE GRADO 924 (las que aplican a este grupo) ==' as '';
SELECT 'cm eliminados en seccion 924 (la seccion del grupo 9503) o con availability para grupo 660/661:' AS info_;
SELECT cm.id, cm.section, s.name, cm.instance, cm.deletioninprogress, cm.visible FROM isi_course_modules cm LEFT JOIN isi_course_sections s ON s.id = cm.section WHERE cm.course = 74 AND (cm.section = 924 OR s.availability LIKE '%704%' OR s.availability LIKE '%660%' OR s.availability LIKE '%661%') AND cm.id NOT IN (SELECT id FROM (SELECT 1 id) z) ORDER BY cm.id;
SELECT '==D. STUDENT 2758 (Leyda) - SUS ARCHIVOS EN MOODLEDATA ==' as '';
SELECT f.id, f.component, f.filearea, f.itemid AS assign_id, f.filename, f.filesize, from_unixtime(f.timecreated) tc FROM isi_files f WHERE f.component = 'assignsubmission_file' AND f.filename <> '.' AND f.userid = 2758 AND f.contextid IN (SELECT id FROM isi_context WHERE contextlevel = 70 AND instanceid = 74) ORDER BY f.itemid;
SELECT '==E. STUDENT 2317 (Yisbel) - SUS ARCHIVOS EN MOODLEDATA ==' as '';
SELECT f.id, f.component, f.filearea, f.itemid AS assign_id, f.filename, f.filesize, from_unixtime(f.timecreated) tc FROM isi_files f WHERE f.component = 'assignsubmission_file' AND f.filename <> '.' AND f.userid = 2317 AND f.contextid IN (SELECT id FROM isi_context WHERE contextlevel = 70 AND instanceid = 74) ORDER BY f.itemid;
